import { genkit } from 'genkit';
import { googleAI } from '@genkit-ai/google-genai';

const ai = genkit({
  plugins: [googleAI()],
});

const PROMPT = 'Tell me a short, original joke. Respond with just the joke, nothing else.';

async function tellJoke(): Promise<string> {
  try {
    const { text } = await ai.generate({
      model: googleAI.model('gemini-2.5-flash'),
      prompt: PROMPT,
    });
    return text;
  } catch (err) {
    console.error('Gemini call failed, falling back to another model:', err);
    const { text } = await ai.generate({
      model: googleAI.model('gemini-3.8-flash'),
      prompt: PROMPT,
    });
    return text;
  }
}

const joke = await tellJoke();
console.log(joke);
